var SUGGEST=['尿不湿','奶粉','湿巾'];
function num(v){
  if(v===null||v===undefined||String(v).trim()==='')return NaN;
  var n=Number(v);
  return isFinite(n)?n:NaN;
}
function r2(n){return Math.round(n*100)/100;}
function fmt(n){return String(r2(n));}
function listOf(s){return s&&Array.isArray(s.items)?s.items:[];}
function isLow(it){return typeof it.low==='number'&&it.qty<it.low;}
function stepOf(it){return it.step>0?it.step:1;}
function ordered(list){
  var low=[],rest=[];
  list.forEach(function(it){(isLow(it)?low:rest).push(it);});
  return low.concat(rest);
}
function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid}=ctx;
  const items=listOf(state);
  if(!ui.view)ui.view='list';

  function h(tag,attrs,...kids){
    return el(tag,attrs||{},...kids.filter(function(x){return x!==null&&x!==undefined&&x!==false;}));
  }
  function fail(e){
    ui.err='保存失败：'+((e&&e.message)||'请重试');
    redraw();
  }
  function adjust(id,dir){
    if(ui.err)ui.err='';
    return update(function(s){
      const next=listOf(s).map(function(it){
        if(it.id!==id)return it;
        return {...it,qty:Math.max(0,r2(it.qty+dir*stepOf(it)))};
      });
      return {...s,items:next};
    }).catch(fail);
  }
  function openAdd(name){
    ui.view='form';ui.editId=null;ui.err='';ui.confirmDel=false;
    ui.draft={name:name||'',qty:'',unit:'',low:'',step:'1'};
    redraw();
  }
  function openEdit(it){
    ui.view='form';ui.editId=it.id;ui.err='';ui.confirmDel=false;
    ui.draft={
      name:it.name,qty:String(it.qty),unit:it.unit||'',
      low:typeof it.low==='number'?String(it.low):'',
      step:String(stepOf(it))
    };
    redraw();
  }
  function cancel(){
    ui.view='list';ui.draft=null;ui.editId=null;ui.err='';ui.confirmDel=false;
    redraw();
  }
  function setErr(msg){ui.err=msg;redraw();}

  function save(){
    const d=ui.draft;
    const name=String(d.name||'').trim();
    if(!name)return setErr('请填写名称');
    const qty=num(d.qty);
    if(!(qty>=0))return setErr('请填写当前数量（不小于 0）');
    const unit=String(d.unit||'').trim();
    let low=null;
    if(String(d.low).trim()!==''){
      low=num(d.low);
      if(!(low>=0))return setErr('快用完数量需为不小于 0 的数字，或留空');
      low=r2(low);
    }
    const step=String(d.step).trim()===''?1:num(d.step);
    if(!(step>0))return setErr('每次增减需大于 0');
    const id=ui.editId;
    const newId=id?null:uid();
    const rec={name:name,qty:r2(qty),unit:unit,low:low,step:r2(step)};
    return commit(function(s){
      const arr=listOf(s);
      const next=id
        ?arr.map(function(it){return it.id===id?{...it,...rec}:it;})
        :arr.concat([{id:newId,...rec}]);
      return {...s,items:next};
    },{view:'list',draft:null,editId:null,err:'',confirmDel:false}).catch(fail);
  }
  function del(){
    const id=ui.editId;
    return commit(function(s){
      return {...s,items:listOf(s).filter(function(it){return it.id!==id;})};
    },{view:'list',draft:null,editId:null,err:'',confirmDel:false}).catch(fail);
  }


  function stepBtn(it,dir){
    const dec=dir<0;
    const st=fmt(stepOf(it));
    const word=dec?'用掉':'买来';
    return h('button',{
      type:'button',class:'stp '+(dec?'dec':'inc'),disabled:!!(dec&&it.qty<=0),
      'aria-label':word+' '+st+(it.unit||'')+'：'+it.name,
      title:word+' '+st+(it.unit||''),
      onclick:function(){adjust(it.id,dir);}
