      h('span',{class:'bs'},dec?'−':'+'),
      h('span',{class:'bl'},word),
      h('span',{class:'bn'},st));
  }
  function tile(it){
    const low=isLow(it);
    const hint=typeof it.low==='number'
      ?'低于 '+fmt(it.low)+(it.unit||'')+' 时提醒'
      :'未设快用完数量';
