      type:'button',class:'main','aria-label':'编辑 '+it.name,
      onclick:function(){openEdit(it);}
    },
      h('span',{class:'l1'},
        h('span',{class:'nm'},it.name),
        low?h('span',{class:'bdg'},'快用完'):null),
      h('span',{class:'l2'},
        h('span',{class:'q'},fmt(it.qty)),
        it.unit?h('span',{class:'u'},it.unit):null),
      h('span',{class:'hint'},hint));
    return h('div',{class:'it'+(low?' low':'')},
      main,
      h('div',{class:'act'},stepBtn(it,-1),stepBtn(it,1)));
  }
  function header(){
    const nLow=items.filter(isLow).length;
    let sub='记录还剩多少';
    if(items.length)sub=nLow?('! '+nLow+' 项快用完'):('共 '+items.length+' 项');
    return h('div',{class:'hd'},
      h('div',{class:'ttl'},
        h('div',{class:'t'},'宝宝用品库存'),
        h('div',{class:'s'+(nLow?' warn':'')},sub)),
      h('button',{type:'button',class:'add',onclick:function(){openAdd('');}},'+ 新增'));
  }
  function chipRow(names,cls){
    return h('div',{class:'chips '+(cls||'')},
      ...names.map(function(n){
        return h('button',{type:'button',class:'chip',onclick:function(){
          if(ui.view==='form'){ui.draft.name=n;redraw();}else{openAdd(n);}
        }},n);
      }));
  }
  function empty(){
    return h('div',{class:'empty'},
      h('div',{class:'et'},'还没有记录用品'),
      h('div',{class:'ed'},'点常用品快速添加，或点右上角新增'),
      chipRow(SUGGEST,''));
  }
  function listView(){
    return h('div',{class:'pg'},
      header(),
      ui.err?h('div',{class:'err'},'! '+ui.err):null,
      items.length
        ?h('div',{class:'list'},...ordered(items).map(tile))
        :empty());
  }

  function fld(label,key,attrs){
    const i=el('input',{
      class:'in',value:ui.draft[key],
      oninput:function(){ui.draft[key]=i.value;},
      onkeydown:function(ev){if(ev.key==='Enter')save();},
      ...attrs
    });
    return h('label',{class:'fld'},h('span',{class:'fl'},label),i);
  }
  function formView(){
    const editing=!!ui.editId;
    const used=items.map(function(x){return x.name;});
    const sug=editing?[]:SUGGEST.filter(function(n){return used.indexOf(n)<0;});
    const numAttrs={type:'number',min:'0',step:'any',inputmode:'decimal'};
    const body=h('div',{class:'fbody'},
      fld('名称','name',{type:'text',placeholder:'如：尿不湿',maxlength:'20'}),
      sug.length?chipRow(sug,'sm'):null,
      h('div',{class:'row2'},
        fld('当前数量','qty',{...numAttrs,placeholder:'0'}),
        fld('单位','unit',{type:'text',placeholder:'片 / 罐 / 包',maxlength:'8'})),
      h('div',{class:'row2'},
        fld('快用完数量','low',{...numAttrs,placeholder:'低于它就提醒'}),
        fld('每次增减','step',{...numAttrs,placeholder:'1'})),
      h('div',{class:'note'},'库存低于「快用完数量」时，这一项会排到列表最前面；留空则不提醒。'));
    let ftr;
    if(ui.confirmDel){
      ftr=h('div',{class:'ftr'},
        h('span',{class:'cd'},'删除「'+String(ui.draft.name||'')+'」？'),
        h('button',{type:'button',class:'btn dng',onclick:del},'确认删除'),
        h('button',{type:'button',class:'btn',onclick:function(){ui.confirmDel=false;redraw();}},'取消'));
    }else{
      ftr=h('div',{class:'ftr'},
        h('button',{type:'button',class:'btn pri',onclick:save},'保存'),
        editing?h('button',{type:'button',class:'btn',onclick:function(){ui.confirmDel=true;ui.err='';redraw();}},'删除'):null);
    }
    return h('div',{class:'pg'},
      h('div',{class:'hd'},
        h('button',{type:'button',class:'back',onclick:cancel},'‹ 返回'),
        h('div',{class:'t'},editing?'编辑用品':'新增用品')),
      body,
      ui.err?h('div',{class:'err'},'! '+ui.err):null,
      ftr);
  }

  if(ui.view==='form'&&ui.draft)root.appendChild(formView());
  else{ui.view='list';root.appendChild(listView());}
}

